input.oldString:
function generateStars() {
    stars.length = 0;
    const starCount = Math.min(200, Math.floor(canvas.width * canvas.height / 20000));
    for (let i = 0; i < starCount; i++) {
      stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        radius: Math.random() * 2 + 0.5,
      });
    }
  }

